# 팩토리얼
def factorial(n):
    if n == 0:   # base case
        return 1
    return n * factorial(n - 1)  # recursive case

# 피보나치 (순수 재귀 — O(2^n))
def fib(n):
    if n <= 1:
        return n
    return fib(n - 1) + fib(n - 2)

